const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
export function projectileDepthPlanePresentation(input, reducedMotion = false) { const overlap = clamp01(input.bodyOverlap), lane = clamp01(input.laneProximity), crowd = clamp01(input.crowd), pressure = clamp01(overlap * .42 + lane * .32 + crowd * .34), relief = input.critical ? .42 : 1; return { pressure, bodyScale: 1, trailScale: Math.max(input.critical ? .84 : .62, 1 - pressure * .28 * relief) * (reducedMotion ? .96 : 1), trailLineScale: Math.max(.72, 1 - pressure * .2), lateralDepthScale: 1 - pressure * .18, presentationOnly: true }; }
export function impactDepthPlanePresentation(input, reducedFlash = false) { const hero = clamp01(input.heroProximity), crowd = clamp01(input.crowd), pressure = clamp01(hero * .58 + crowd * .42), flash = reducedFlash ? .9 : 1, fillScale = Math.max(input.critical ? .78 : .58, 1 - pressure * .34), edgeScale = Math.max(fillScale, .82 + (1 - pressure) * .18), fillAlphaScale = Math.max(input.critical ? .64 : .38, 1 - pressure * .48) * flash, edgeAlphaScale = Math.max(fillAlphaScale, .74 + (1 - pressure) * .2); return { pressure, fillScale, edgeScale, fillAlphaScale, edgeAlphaScale, presentationOnly: true }; }
export function hazardDepthPlanePresentation(input, reducedFlash = false) { const lane = clamp01(input.laneProximity), crowd = clamp01(input.crowd), pressure = clamp01(lane * .48 + crowd * .52), flash = reducedFlash ? .9 : 1; return { pressure, edgeAlphaScale: input.telegraph || input.critical ? Math.max(.94, .99 * (reducedFlash ? .98 : 1)) : Math.max(.72, 1 - pressure * .2), fillScale: Math.max(input.critical ? .72 : .54, 1 - pressure * .38), fillAlphaScale: Math.max(input.critical ? .58 : .28, 1 - pressure * .5) * flash, presentationOnly: true }; }
export function safeLaneContourDepthPresentation(input, reducedFlash = false) { const confidence = clamp01(input.confidence), pressure = clamp01(input.pressure); return { contourAlphaScale: input.visible ? 1 + pressure * (.08 + .04 * confidence) * (reducedFlash ? .78 : 1) : 1, contourWidthScale: input.visible ? 1 + pressure * .16 : 1, fillScale: input.visible ? Math.max(.78, 1 - pressure * .12) : 1, presentationOnly: true }; }
export function specialistRimDepthPresentation(input, reducedMotion = false) { const hazard = clamp01(input.hazardPressure), crowd = clamp01(input.crowd), pressure = clamp01(hazard * .54 + crowd * .46), action = input.owner === 'special' ? 1 : input.owner === 'attack' ? .9 : input.owner === 'hit' ? .72 : input.owner === 'recovery' ? .5 : .2; return { pressure, bodyScale: 1, rimAlphaScale: Math.max(input.critical ? .82 : .72, .76 + action * .18 - pressure * .1), rimWidthScale: Math.max(.82, 1 - pressure * .14), secondaryScale: Math.max(.58, 1 - pressure * .34) * (reducedMotion ? .94 : 1), presentationOnly: true }; }
export function depthPlaneBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const critical = clamp01(Math.max(0, input.criticalCount) / 3), load = clamp01((input.projectileCount + input.impactCount + input.hazardCount * 1.3 + input.silhouetteCount) / 34), stress = clamp01(load * .86 + critical * .18); return { stress, canonicalScale: 1, criticalAlphaScale: 1, safeLaneScale: input.safeLaneVisible ? 1 + stress * .08 * (reducedFlash ? .78 : 1) : 1, backgroundScale: Math.max(.64, 1 - stress * .3) * (reducedMotion ? .96 : 1), secondaryAlphaScale: Math.max(.58, 1 - stress * .34) * (reducedFlash ? .94 : 1), presentationOnly: true }; }
